from typing import List, Tuple

import torch
import torch.nn as nn
import torch.nn.functional as F
import torch.distributed as dist


def _dist_is_initialized() -> bool:
    return dist.is_available() and dist.is_initialized()


def _get_world_size() -> int:
    if _dist_is_initialized():
        return dist.get_world_size()
    return 1


def _get_rank() -> int:
    if _dist_is_initialized():
        return dist.get_rank()
    return 0


def _partition_sizes(total_size: int, world_size: int) -> List[int]:
    if world_size <= 0:
        raise ValueError("world_size must be positive")
    base = total_size // world_size
    remainder = total_size % world_size
    return [base + (1 if rank < remainder else 0) for rank in range(world_size)]


def _start_end_from_sizes(sizes: List[int], rank: int) -> Tuple[int, int]:
    start = sum(sizes[:rank])
    end = start + sizes[rank]
    return start, end


class _AllGatherLastDim(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input: torch.Tensor) -> torch.Tensor:
        world_size = _get_world_size()
        rank = _get_rank()
        ctx.world_size = world_size
        ctx.rank = rank

        if world_size == 1:
            ctx.sizes = [input.shape[-1]]
            return input

        local_size = torch.tensor([input.shape[-1]], device=input.device, dtype=torch.long)
        size_list = [torch.empty_like(local_size) for _ in range(world_size)]
        dist.all_gather(size_list, local_size)
        sizes = [int(size.item()) for size in size_list]
        ctx.sizes = sizes
        max_size = max(sizes)

        if input.shape[-1] < max_size:
            pad_amount = max_size - input.shape[-1]
            input_padded = F.pad(input, (0, pad_amount))
        else:
            input_padded = input

        outputs = [torch.empty_like(input_padded) for _ in range(world_size)]
        dist.all_gather(outputs, input_padded)
        trimmed = [tensor[..., :sizes[idx]] for idx, tensor in enumerate(outputs)]
        return torch.cat(trimmed, dim=-1)

    @staticmethod
    def backward(ctx, grad_output: torch.Tensor):
        if ctx.world_size == 1:
            return grad_output
        sizes = ctx.sizes
        rank = ctx.rank
        start = sum(sizes[:rank])
        end = start + sizes[rank]
        grad_input = grad_output[..., start:end].contiguous()
        return grad_input


class _AllReduceSum(torch.autograd.Function):
    @staticmethod
    def forward(ctx, input: torch.Tensor) -> torch.Tensor:
        world_size = _get_world_size()
        ctx.world_size = world_size

        if world_size == 1:
            return input

        output = input.clone()
        dist.all_reduce(output, op=dist.ReduceOp.SUM)
        return output

    @staticmethod
    def backward(ctx, grad_output: torch.Tensor):
        if ctx.world_size == 1:
            return grad_output
        # For a sum-reduction, the gradient w.r.t. each input is the upstream gradient.
        return grad_output


class ColumnParallelLinear(nn.Module):
    def __init__(self, in_features: int, out_features: int, bias: bool, master_weight: torch.Tensor):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        world_size = _get_world_size()
        rank = _get_rank()
        sizes = _partition_sizes(out_features, world_size)
        start, end = _start_end_from_sizes(sizes, rank)

        if master_weight is None:
            weight = torch.empty(out_features, in_features)
            nn.init.kaiming_uniform_(weight, a=math.sqrt(5))
        else:
            weight = master_weight

        if weight.shape != (out_features, in_features):
            raise ValueError(
                f"master_weight must have shape ({out_features}, {in_features}), got {tuple(weight.shape)}"
            )

        local_weight = weight[start:end, :].contiguous().clone()
        self.weight = nn.Parameter(local_weight)

        if bias:
            bias_tensor = torch.zeros(sizes[rank], device=weight.device, dtype=weight.dtype)
            self.bias = nn.Parameter(bias_tensor)
        else:
            self.bias = None

    def forward(self, input: torch.Tensor) -> torch.Tensor:
        local_output = F.linear(input, self.weight, self.bias)
        return _AllGatherLastDim.apply(local_output)


class RowParallelLinear(nn.Module):
    def __init__(self, in_features: int, out_features: int, bias: bool, master_weight: torch.Tensor):
        super().__init__()
        self.in_features = in_features
        self.out_features = out_features

        world_size = _get_world_size()
        rank = _get_rank()
        sizes = _partition_sizes(in_features, world_size)
        start, end = _start_end_from_sizes(sizes, rank)
        self.input_start = start
        self.input_end = end

        if master_weight is None:
            weight = torch.empty(out_features, in_features)
            nn.init.kaiming_uniform_(weight, a=math.sqrt(5))
        else:
            weight = master_weight

        if weight.shape != (out_features, in_features):
            raise ValueError(
                f"master_weight must have shape ({out_features}, {in_features}), got {tuple(weight.shape)}"
            )

        local_weight = weight[:, start:end].contiguous().clone()
        self.weight = nn.Parameter(local_weight)

        if bias:
            bias_tensor = torch.zeros(out_features, device=weight.device, dtype=weight.dtype)
            self.bias = nn.Parameter(bias_tensor)
        else:
            self.bias = None

    def forward(self, input: torch.Tensor) -> torch.Tensor:
        input_slice = input[..., self.input_start:self.input_end]
        local_output = F.linear(input_slice, self.weight, bias=None)
        output = _AllReduceSum.apply(local_output)
        if self.bias is not None:
            output = output + self.bias
        return output
